using System;
using System.ComponentModel;
using System.Drawing;
using System.Windows.Forms;
namespace ZenForms.Core
{
    [Category("ZenForms Modern Components")]
    [Description("HSV color studio with HEX codes and instantly generated harmonic palettes.")]
    public class ZenColorStudio : UserControl
    {
        private readonly TrackBar hue, saturation, brightness; private readonly TextBox hex; private readonly Panel swatch; private readonly Panel[] chips = new Panel[5]; private Color selected = ZenTheme.Primary; private bool updating;
        [Category("ZenForms Color"), DefaultValue(typeof(Color), "124, 92, 255")] public Color SelectedColor { get { return selected; } set { selected = value; UpdateFromColor(value); } }
        [Browsable(false)] public string HexValue { get { return "#" + selected.R.ToString("X2") + selected.G.ToString("X2") + selected.B.ToString("X2"); } }
        public event EventHandler SelectedColorChanged;
        public ZenColorStudio() { Size = new Size(420, 300); MinimumSize = new Size(300, 250); BackColor = ZenTheme.Surface; Label title = new Label { Dock = DockStyle.Top, Height = 35, Text = "COLOR STUDIO", Font = new Font("Segoe UI Semibold", 10f), ForeColor = ZenTheme.Foreground, TextAlign = ContentAlignment.MiddleLeft, Padding = new Padding(10, 0, 0, 0) }; TableLayoutPanel layout = new TableLayoutPanel { Dock = DockStyle.Fill, ColumnCount = 2, RowCount = 5, Padding = new Padding(10), BackColor = ZenTheme.Surface }; layout.ColumnStyles.Add(new ColumnStyle(SizeType.Absolute, 94)); layout.ColumnStyles.Add(new ColumnStyle(SizeType.Percent, 100)); for (int i = 0; i < 5; i++) layout.RowStyles.Add(new RowStyle(i == 3 ? SizeType.Absolute : SizeType.Percent, i == 3 ? 38 : 20)); hue = MakeSlider(0, 359); saturation = MakeSlider(0, 100); brightness = MakeSlider(0, 100); AddRow(layout, 0, "HUE", hue); AddRow(layout, 1, "SATURATION", saturation); AddRow(layout, 2, "BRIGHTNESS", brightness); swatch = new Panel { Dock = DockStyle.Fill, BackColor = selected, Margin = new Padding(3) }; hex = new TextBox { Dock = DockStyle.Fill, Text = "#7C5CFF", BackColor = ZenTheme.SurfaceRaised, ForeColor = ZenTheme.Foreground, Font = new Font("Consolas", 11f), BorderStyle = BorderStyle.FixedSingle, TextAlign = HorizontalAlignment.Center }; TableLayoutPanel colorRow = new TableLayoutPanel { Dock = DockStyle.Fill, ColumnCount = 2, RowCount = 1, Margin = new Padding(0) }; colorRow.ColumnStyles.Add(new ColumnStyle(SizeType.Percent, 100)); colorRow.ColumnStyles.Add(new ColumnStyle(SizeType.Absolute, 112)); colorRow.Controls.Add(swatch, 0, 0); colorRow.Controls.Add(hex, 1, 0); layout.Controls.Add(MakeLabel("PREVIEW"), 0, 3); layout.Controls.Add(colorRow, 1, 3); FlowLayoutPanel palette = new FlowLayoutPanel { Dock = DockStyle.Fill, WrapContents = false, BackColor = ZenTheme.Surface, Padding = new Padding(0, 4, 0, 0) }; for (int i = 0; i < chips.Length; i++) { Panel chip = new Panel { Size = new Size(34, 25), Margin = new Padding(2), BorderStyle = BorderStyle.FixedSingle, Cursor = Cursors.Hand }; chips[i] = chip; palette.Controls.Add(chip); chip.Click += (s, e) => SelectedColor = chip.BackColor; } layout.Controls.Add(MakeLabel("HARMONY"), 0, 4); layout.Controls.Add(palette, 1, 4); Controls.Add(layout); Controls.Add(title); hue.ValueChanged += (s, e) => UpdateFromHsv(); saturation.ValueChanged += (s, e) => UpdateFromHsv(); brightness.ValueChanged += (s, e) => UpdateFromHsv(); hex.KeyDown += (s, e) => { if (e.KeyCode == Keys.Enter) { ApplyHex(); e.SuppressKeyPress = true; } }; hex.Leave += (s, e) => ApplyHex(); UpdateFromColor(selected); }
        private static TrackBar MakeSlider(int min, int max) { return new TrackBar { Dock = DockStyle.Fill, Minimum = min, Maximum = max, TickStyle = TickStyle.None, SmallChange = 1, LargeChange = 10, Height = 30, BackColor = ZenTheme.Surface }; }
        private static Label MakeLabel(string text) { return new Label { Dock = DockStyle.Fill, Text = text, Font = new Font("Segoe UI", 7.5f, FontStyle.Bold), ForeColor = ZenTheme.Muted, TextAlign = ContentAlignment.MiddleLeft }; }
        private static void AddRow(TableLayoutPanel t, int row, string label, Control control) { t.Controls.Add(MakeLabel(label), 0, row); t.Controls.Add(control, 1, row); }
        private void UpdateFromColor(Color c) { if (hue == null) return; updating = true; float h, s, v; RgbToHsv(c, out h, out s, out v); hue.Value = Math.Max(hue.Minimum, Math.Min(hue.Maximum, (int)h)); saturation.Value = Math.Max(0, Math.Min(100, (int)(s * 100))); brightness.Value = Math.Max(0, Math.Min(100, (int)(v * 100))); updating = false; ApplyColor(c); }
        private void UpdateFromHsv() { if (updating) return; ApplyColor(HsvToRgb(hue.Value, saturation.Value / 100f, brightness.Value / 100f)); }
        private void ApplyColor(Color c) { selected = c; swatch.BackColor = c; hex.Text = HexValue; UpdatePalette(); EventHandler h = SelectedColorChanged; if (h != null) h(this, EventArgs.Empty); }
        private void ApplyHex() { string value = hex.Text.Trim().TrimStart('#'); try { if (value.Length == 6) SelectedColor = ColorTranslator.FromHtml("#" + value); } catch { hex.Text = HexValue; } }
        private void UpdatePalette() { if (chips[0] == null) return; float h, s, v; RgbToHsv(selected, out h, out s, out v); float[] offsets = { 0, 30, 60, 180, 210 }; for (int i = 0; i < chips.Length; i++) chips[i].BackColor = HsvToRgb((h + offsets[i]) % 360, s, Math.Max(.35f, v)); }
        private static void RgbToHsv(Color c, out float h, out float s, out float v) { float r = c.R / 255f, g = c.G / 255f, b = c.B / 255f, max = Math.Max(r, Math.Max(g, b)), min = Math.Min(r, Math.Min(g, b)), d = max - min; h = 0; if (d > 0) { if (max == r) h = 60 * ((g - b) / d % 6); else if (max == g) h = 60 * ((b - r) / d + 2); else h = 60 * ((r - g) / d + 4); } if (h < 0) h += 360; s = max == 0 ? 0 : d / max; v = max; }
        private static Color HsvToRgb(float h, float s, float v) { float c = v * s, x = c * (1 - Math.Abs((h / 60f) % 2 - 1)), m = v - c, r = 0, g = 0, b = 0; if (h < 60) { r = c; g = x; } else if (h < 120) { r = x; g = c; } else if (h < 180) { g = c; b = x; } else if (h < 240) { g = x; b = c; } else if (h < 300) { r = x; b = c; } else { r = c; b = x; } return Color.FromArgb((int)((r + m) * 255), (int)((g + m) * 255), (int)((b + m) * 255)); }
    }
}

